  transition={{ duration: 0.5 }}
>
  Scroll to reveal
</motion.div>

import { motion, AnimatePresence } from 'framer-motion';

<AnimatePresence>
  {items.map((item) => (
    <motion.div
      key={item.id}
      layout
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      {item.content}
    </motion.div>
  ))}
</AnimatePresence>
